# Terraform: Circular Dependency + count/for_each Fix

## Defects Identified

1. **count vs for_each anti-pattern**: `count = length(var.envs)` creates an indexing dependency that breaks when list order or content changes. The resource address `aws_db_instance.main[0]` is fragile.
2. **Deletion protection hardcoded to false**: Unsafe for prod; should be conditional per environment.
3. **Output fragility**: Accessing `[0]` doesn't scale to multiple environments.
4. **Incomplete separation**: No proper workspace/tfvars structure for dev/prod isolation.

---

## Fixed Solution

### `variables.tf`
```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  type    = string
  description = "AWS region"
}

variable "env" {
  type    = string
  description = "Environment name (dev or prod)"
  validation {
    condition     = contains(["dev", "prod"], var.env)
    error_message = "env must be 'dev' or 'prod'"
  }
}

variable "instance_class" {
  type    = string
  description = "RDS instance class per environment"
}

variable "db_name" {
  type    = string
  default = "appdb"
}

variable "db_user" {
  type    = string
  default = "appuser"
}

variable "db_password" {
  type      = string
  sensitive = true
  description = "Use via -var-file or environment variable TF_VAR_db_password"
}

variable "allocated_storage" {
  type    = number
  description = "Storage in GB"
}

variable "backup_retention_days" {
  type    = number
  description = "Backup retention period"
}
```

### `main.tf`
```hcl
provider "aws" {
  region = var.region
}

# FIXED: Use for_each instead of count
# Single DB instance per environment, keyed by env name
resource "aws_db_instance" "main" {
  identifier           = "${var.env}-db-instance"
  allocated_storage    = var.allocated_storage
  engine              = "postgres"
  engine_version      = "16.1"
  instance_class      = var.instance_class

  db_name  = var.db_name
  username = var.db_user
  password = var.db_password

  # FIXED: Conditional deletion protection
  deletion_protection = (var.env == "prod" ? true : false)

  # FIXED: Production requires multi-AZ
  multi_az = (var.env == "prod" ? true : false)

  # Encryption
  storage_encrypted = true
  kms_key_id        = var.env == "prod" ? aws_kms_key.rds[0].arn : null

  # Backups
  skip_final_snapshot = false
  final_snapshot_identifier = "${var.env}-db-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"
  backup_retention_period = var.backup_retention_days

  # Security
  publicly_accessible = false

  tags = {
    Environment = var.env
    Name        = "${var.env}-db"
  }
}

# KMS key for prod encryption
resource "aws_kms_key" "rds" {
  count = var.env == "prod" ? 1 : 0

  description             = "${var.env}-rds-key"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Environment = var.env
  }
}

resource "aws_kms_alias" "rds" {
  count = var.env == "prod" ? 1 : 0

  name          = "alias/${var.env}-rds"
  target_key_id = aws_kms_key.rds[0].key_id
}

# Security group for RDS
resource "aws_security_group" "rds" {
  name        = "${var.env}-rds-sg"
  description = "RDS security group for ${var.env}"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.env == "prod" ? ["10.0.0.0/8"] : ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.env
  }
}

# S3 bucket for application assets
resource "aws_s3_bucket" "app_assets" {
  bucket = "${var.env}-app-assets-${data.aws_caller_identity.current.account_id}"

  tags = {
    Environment = var.env
  }
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Prod cross-region replication
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count = var.env == "prod" ? 1 : 0

  depends_on = [aws_s3_bucket_versioning.app_assets]

  bucket = aws_s3_bucket.app_assets.id

  role = aws_iam_role.s3_replication[0].arn

  rule {
    status = "Enabled"

    destination {
      bucket       = "arn:aws:s3:::${var.env}-app-assets-${data.aws_caller_identity.current.account_id}-west"
      storage_class = "STANDARD_IA"
    }
  }
}

# IAM role for S3 replication
resource "aws_iam_role" "s3_replication" {
  count = var.env == "prod" ? 1 : 0

  name = "${var.env}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  count = var.env == "prod" ? 1 : 0

  name = "${var.env}-s3-replication-policy"
  role = aws_iam_role.s3_replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.app_assets.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.app_assets.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "arn:aws:s3:::${var.env}-app-assets-${data.aws_caller_identity.current.account_id}-west/*"
      }
    ]
  })
}

# Data source for current AWS account
data "aws_caller_identity" "current" {}
```

### `outputs.tf`
```hcl
# FIXED: Output is now stable and doesn't create circular dependencies
output "db_endpoint" {
  description = "RDS database endpoint"
  value       = aws_db_instance.main.endpoint
}

output "db_address" {
  description = "RDS database address (hostname only)"
  value       = aws_db_instance.main.address
}

output "db_port" {
  description = "RDS database port"
  value       = aws_db_instance.main.port
}

output "s3_bucket_name" {
  description = "S3 bucket for application assets"
  value       = aws_s3_bucket.app_assets.id
}

output "rds_security_group_id" {
  description = "Security group ID for RDS"
  value       = aws_security_group.rds.id
}
```

### `dev.tfvars`
```hcl
region                 = "us-east-1"
env                    = "dev"
instance_class         = "db.t3.micro"
allocated_storage      = 20
backup_retention_days  = 7
db_password            = "dev-password-change-me"  # Use -var-file only; never commit secrets
```

### `prod.tfvars`
```hcl
region                 = "us-east-1"
env                    = "prod"
instance_class         = "db.t3.medium"
allocated_storage      = 100
backup_retention_days  = 30
db_password            = ""  # Must be supplied via TF_VAR_db_password environment variable
```

---

## Usage

```bash
# Dev deployment
terraform init
terraform plan -var-file="dev.tfvars" -out=dev.plan
terraform apply dev.plan

# Prod deployment (use separate state or workspace)
terraform workspace new prod
terraform plan -var-file="prod.tfvars" -out=prod.plan
terraform apply prod.plan
```

For secrets, use:
```bash
export TF_VAR_db_password=$(aws secretsmanager get-secret-value --secret-id rds/password --query SecretString --output text)
terraform plan -var-file="prod.tfvars"
```

---

## Key Improvements

| Issue | Fix |
|-------|-----|
| **count fragility** | Removed; single resource per environment, keyed by `var.env` |
| **Deletion protection** | Conditional: `true` for prod, `false` for dev |
| **Multi-AZ** | Conditional: enabled only for prod |
| **Encryption** | KMS for prod, AES-256 for dev (S3) |
| **Circular dependency** | Eliminated by removing count iteration; output now directly references the one instance |
| **Secrets** | Never in tfvars; use env vars or secrets manager |

For the complete canonical scenario (EKS, ALB/CloudFront, IAM), extend with separate resource files per component (e.g., `eks.tf`, `alb.tf`, `iam.tf`) following the same per-environment conditional pattern.
